from PIL import Image
import numpy as np
im=np.asarray(Image.open('first_frame.png').convert('RGB')).astype(float)
# Compare actual RGB direct ball vs mirror ball: direct normalized colors; mirror ball mostly low R due low light. derive base ball color.
for label,cx,cy,r in [('direct',101.7,95,9.2),('mirror',191.5,76,7.0)]:
 Y=[]
 for yy in range(int(cy-r),int(cy+r)+1):
  for xx in range(int(cx-r),int(cx+r)+1):
   if np.hypot(xx-cx,yy-cy)<r-1: Y.append(im[yy,xx])
 Y=np.array(Y)
 print(label,'mean',Y.mean(0),'p10',np.percentile(Y,10,axis=0),'p90',np.percentile(Y,90,axis=0))
